# Distributed SQL Query Execution Engine in C#

Below is a modular design for a distributed SQL query execution engine in C# with the three requested components. This implementation focuses on the core operators while providing the foundation for a full distributed system.

## Core Architecture Overview

```csharp
public interface IQueryOperator
{
    Task ExecuteAsync(QueryExecutionContext context);
}

public class QueryExecutionContext
{
    public IReadOnlyDictionary<string, DataPartition> InputPartitions { get; }
    public IReadOnlyDictionary<string, DataPartition> OutputPartitions { get; }
    public MemoryManager MemoryManager { get; }
    public CancellationToken CancellationToken { get; }
    // Other context properties...
}
```

## 1. Network Exchange Operator

Handles buffering and routing data partitions between nodes:

```csharp
public class NetworkExchangeOperator : IQueryOperator
{
    private readonly INodeCommunication _communication;
    private readonly IPartitionRouter _router;
    private readonly IBufferManager _bufferManager;
    private readonly int _bufferSize;

    public NetworkExchangeOperator(
        INodeCommunication communication,
        IPartitionRouter router,
        IBufferManager bufferManager,
        int bufferSize = 1024)
    {
        _communication = communication ?? throw new ArgumentNullException(nameof(communication));
        _router = router ?? throw new ArgumentNullException(nameof(router));
        _bufferManager = bufferManager ?? throw new ArgumentNullException(nameof(bufferManager));
        _bufferSize = bufferSize;
    }

    public async Task ExecuteAsync(QueryExecutionContext context)
    {
        // Receive partitions from other nodes
        var receivedPartitions = await _communication.ReceivePartitionsAsync(context.CancellationToken);

        // Route partitions to appropriate consumers
        foreach (var partition in receivedPartitions)
        {
            var targetNode = _router.GetTargetNode(partition);
            var buffer = _bufferManager.GetBuffer(partition.Key, _bufferSize);

            await buffer.WriteAsync(partition.Data, context.CancellationToken);
            await _communication.SendToNodeAsync(buffer, targetNode, context.CancellationToken);
        }

        // Process locally buffered partitions
        var localBuffers = _bufferManager.GetLocalBuffers();
        foreach (var buffer in localBuffers)
        {
            context.OutputPartitions[buffer.Key] = buffer.Value;
        }
    }
}

// Supporting interfaces
public interface INodeCommunication
{
    Task<Dictionary<string, DataPartition>> ReceivePartitionsAsync(CancellationToken cancellationToken);
    Task SendToNodeAsync(IBuffer buffer, string targetNode, CancellationToken cancellationToken);
}

public interface IPartitionRouter
{
    string GetTargetNode(DataPartition partition);
}

public interface IBufferManager
{
    IBuffer GetBuffer(string partitionKey, int size);
    Dictionary<string, DataPartition> GetLocalBuffers();
}
```

## 2. Hash Aggregation Operator

Groups records in memory with spill-to-disk capability:

```csharp
public class HashAggregationOperator : IQueryOperator
{
    private readonly IHashTableManager _hashTableManager;
    private readonly IDiskSpillManager _spillManager;
    private readonly int _maxMemoryUsage;
    private readonly int _spillThreshold;

    public HashAggregationOperator(
        IHashTableManager hashTableManager,
        IDiskSpillManager spillManager,
        int maxMemoryUsage = 1024 * 1024 * 1024, // 1GB
        int spillThreshold = 80) // 80% of max memory
    {
        _hashTableManager = hashTableManager ?? throw new ArgumentNullException(nameof(hashTableManager));
        _spillManager = spillManager ?? throw new ArgumentNullException(nameof(spillManager));
        _maxMemoryUsage = maxMemoryUsage;
        _spillThreshold = spillThreshold;
    }

    public async Task ExecuteAsync(QueryExecutionContext context)
    {
        var inputPartitions = context.InputPartitions;
        var outputPartitions = context.OutputPartitions;

        // Initialize hash tables
        var hashTables = new Dictionary<string, HashTable>();

        foreach (var partition in inputPartitions)
        {
            var key = partition.Key;
            var data = partition.Value;

            // Create or get existing hash table
            if (!hashTables.TryGetValue(key, out var hashTable))
            {
                hashTable = _hashTableManager.CreateHashTable(key);
                hashTables[key] = hashTable;
            }

            // Process records and check memory usage
            var records = data.GetRecords();
            foreach (var record in records)
            {
                var groupKey = record.GetGroupKey();

                // Check if we need to spill
                if (_hashTableManager.CurrentMemoryUsage > _maxMemoryUsage * _spillThreshold / 100)
                {
                    await _spillManager.SpillHashTableAsync(hashTable, context.MemoryManager);
                }

                // Add to hash table
                hashTable.Add(record);
            }
        }

        // Finalize hash tables (combine spills)
        foreach (var hashTable in hashTables.Values)
        {
            await hashTable.FinalizeAsync();
            outputPartitions[hashTable.Key] = hashTable.ToDataPartition();
        }
    }
}

// Supporting interfaces
public interface IHashTableManager
{
    HashTable CreateHashTable(string key);
    long CurrentMemoryUsage { get; }
}

public interface IDiskSpillManager
{
    Task SpillHashTableAsync(HashTable hashTable, MemoryManager memoryManager);
}

public class HashTable
{
    private readonly Dictionary<object, List<Record>> _buckets;
    private readonly object _lock = new object();

    public string Key { get; }
    public long MemoryUsage { get; private set; }

    public HashTable(string key)
    {
        Key = key;
        _buckets = new Dictionary<object, List<Record>>(1024);
    }

    public void Add(Record record)
    {
        lock (_lock)
        {
            var groupKey = record.GetGroupKey();
            var bucket = _buckets.GetOrAdd(groupKey, _ => new List<Record>());

            bucket.Add(record);
            MemoryUsage += record.EstimatedMemorySize();
        }
    }

    public async Task FinalizeAsync()
    {
        // Combine all records in each bucket
        foreach (var bucket in _buckets.Values)
        {
            // Sort records if needed
            bucket.Sort((r1, r2) => r1.CompareTo(r2));
        }
    }

    public DataPartition ToDataPartition()
    {
        // Convert hash table to DataPartition format
        return new DataPartition(Key, new InMemoryDataStore(_buckets));
    }
}
```

## 3. Disk Spill Manager

Handles spilling intermediate hash tables to disk:

```csharp
public class DiskSpillManager : IDiskSpillManager
{
    private readonly IStorageService _storageService;
    private readonly string _spillDirectory;
    private readonly int _spillChunkSize;

    public DiskSpillManager(
        IStorageService storageService,
        string spillDirectory = "spill_directory",
        int spillChunkSize = 1024 * 1024) // 1MB chunks
    {
        _storageService = storageService ?? throw new ArgumentNullException(nameof(storageService));
        _spillDirectory = spillDirectory;
        _spillChunkSize = spillChunkSize;
    }

    public async Task SpillHashTableAsync(HashTable hashTable, MemoryManager memoryManager)
    {
        // Create spill file path
        var spillFilePath = Path.Combine(_spillDirectory, $"{hashTable.Key}_spill_{DateTime.UtcNow:yyyyMMddHHmmss}.bin");

        // Write hash table to disk in chunks
        using var spillStream = await _storageService.CreateFileAsync(spillFilePath);
        var buffer = new byte[_spillChunkSize];

        // Serialize and write each bucket
        foreach (var bucket in hashTable.GetBuckets())
        {
            var serialized = SerializeBucket(bucket.Value);
            await spillStream.WriteAsync(serialized, 0, serialized.Length);
        }

        // Update memory manager with spill file
        memoryManager.RegisterSpillFile(spillFilePath, hashTable.MemoryUsage);
    }

