public interface IStorageService
{
    Task<Stream> CreateFileAsync(string filePath);
    Task<Stream> OpenFileAsync(string filePath);
    Task DeleteFileAsync(string filePath);
}

public class MemoryManager
{
    private readonly Dictionary<string, long> _spillFiles = new Dictionary<string, long>();
    private long _currentMemoryUsage;

    public long CurrentMemoryUsage => _currentMemoryUsage;

    public void RegisterSpillFile(string filePath, long size)
    {
        _spillFiles[filePath] = size;
        _currentMemoryUsage -= size;
    }

    public void RegisterMemoryUsage(long size)
    {
        _currentMemoryUsage += size;
    }

    public void ReleaseMemory(long size)
    {
        _currentMemoryUsage -= size;
    }
}
